/* Mission Globe — ported from the "Mission Globe" artifact (claude.ai/artifact/BKzTHxg7x2r57HYMJe3H7d)
   into Section 2 of the Air Methods homepage. The HUD-to-headline alignment is done in CSS
   (coverage.css) instead; everything else is the artifact's code and data.

   Tuning panel: add ?controls to the page URL. Tweaks persist in this browser; "Copy settings"
   exports JSON that can be pasted into window.MISSION_GLOBE_CONFIG (set before this module loads)
   or promoted to the defaults below. Panel code is from claude-code-handoff/mission-globe.

   Bases and volumes are PLACEHOLDERS — swap BASES for the client's real list. */
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.min.js";

const CONTROLS = new URLSearchParams(location.search).has("controls");

/* =========================================================
   DATA — swap these for the client's real list.
   flightsPerYear drives launch frequency for each base.
   ========================================================= */
const BASES = [
  ["DEN","Denver, CO",39.74,-104.99,1100],["COS","Colorado Springs, CO",38.83,-104.82,720],["GJT","Grand Junction, CO",39.06,-108.55,480],
  ["SLC","Salt Lake City, UT",40.76,-111.89,950],["BOI","Boise, ID",43.62,-116.20,610],["PHX","Phoenix, AZ",33.45,-112.07,1050],
  ["TUS","Tucson, AZ",32.22,-110.97,640],["ABQ","Albuquerque, NM",35.08,-106.65,700],["LAS","Las Vegas, NV",36.17,-115.14,760],
  ["RNO","Reno, NV",39.53,-119.81,520],["SMF","Sacramento, CA",38.58,-121.49,880],["FAT","Fresno, CA",36.74,-119.79,690],
  ["PDX","Portland, OR",45.52,-122.68,820],["GEG","Spokane, WA",47.66,-117.43,560],["BIL","Billings, MT",45.78,-108.50,430],
  ["RAP","Rapid City, SD",44.08,-103.23,390],["OMA","Omaha, NE",41.26,-95.93,640],["ICT","Wichita, KS",37.69,-97.34,520],
  ["OKC","Oklahoma City, OK",35.47,-97.52,780],["DFW","Dallas, TX",32.78,-96.80,1150],["SAT","San Antonio, TX",29.42,-98.49,900],
  ["HOU","Houston, TX",29.76,-95.37,1120],["LIT","Little Rock, AR",34.75,-92.29,560],["MEM","Memphis, TN",35.15,-90.05,700],
  ["BNA","Nashville, TN",36.16,-86.78,860],["TYS","Knoxville, TN",35.96,-83.92,590],["BHM","Birmingham, AL",33.52,-86.80,680],
  ["ATL","Atlanta, GA",33.75,-84.39,1080],["JAX","Jacksonville, FL",30.33,-81.66,740],["MCO","Orlando, FL",28.54,-81.38,820],
  ["CLT","Charlotte, NC",35.23,-80.84,790],["RIC","Richmond, VA",37.54,-77.44,610],["PIT","Pittsburgh, PA",40.44,-79.99,730],
  ["CMH","Columbus, OH",39.96,-83.00,690],["IND","Indianapolis, IN",39.77,-86.16,720],["STL","St. Louis, MO",38.63,-90.20,810],
  ["MCI","Kansas City, MO",39.10,-94.58,760],["MSP","Minneapolis, MN",44.98,-93.27,870],["DSM","Des Moines, IA",41.59,-93.62,480],
  ["MSN","Madison, WI",43.07,-89.40,450],["YYC","Calgary, AB",51.05,-114.07,640],["YWG","Winnipeg, MB",49.90,-97.14,410],
  ["ALB","Albany, NY",42.65,-73.75,520],
].map(([id,name,lat,lon,fpy]) => ({id,name,lat,lon,fpy}));

const MASK = (() => { // 1-bit land mask, 0.2° cells, lon -200→-5, lat -58→84 — rasterized from Natural Earth 1:50m land
  const bin = atob(""); const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8;
})();
const MASK_RES = 0.2, MASK_LON0 = -200, MASK_LAT0 = -58, MASK_W = 975, MASK_H = 710;

/* ========================================================= */
const FRAMINGS = {
  "North America":        { lat: 40, lon: -97,  dist: 1.21, tilt: 18, sweep: 12 },
  "Regional (West)":      { lat: 38, lon: -109, dist: 0.62, tilt: 24, sweep: 5 },
  "Regional (Southeast)": { lat: 33, lon: -86,  dist: 0.58, tilt: 24, sweep: 5 },
};
const params = {
  accent: "#406de7",
  timeframe: "7 days",
  loopSeconds: 60,
  activity: 1,
  flightSeconds: 1.6,
  trail: 0.55,
  trailWidth: 3.6,
  arcHeight: 1,
  distanceScale: 2.2,
  framing: "North America",
  tilt: 21,
  offset: 23,
  axisTilt: 18,
  zoom: 0.92,
  graticule: true,
  hud: true,
  inverted: false,
  background: "#0c223f",
  bgMode: "Linear gradient",
  background2: "#040b17",
  bgAngle: 178,
  bgX: 68,
  bgY: 42,
  missionColor: "#dce740",   /* Dots + streaks: no brand token for this yellow-green */
  globeColor: "#0a1424", globeMatchBg: false, globeShift: -0.06, globeOpacity: 1,
  rimColor: "#406de7", rimStrength: 0.35, rimTightness: 3,
  haloOn: true, haloColor: "#406de7", haloStrength: 0.55, haloSize: 1.14,
  landColor: "#546e99", landFront: 0.8, landEdge: 0.35,
  gridColor: "#1a2a44", gridOpacity: 0.55,
  lightStrength: 0, lightAngle: -40, lightHeight: 30,
  showCopy: true,
  showLegend: true,
  showShade: true,
  dotDensity: 4,
  landMode: "Elevation lines",
  lineSpacing: 0.19, lineMin: 0.1, lineMax: 0.75, lineContrast: 0.6, lineLift: 0.8, lineAngle: 0, lineOpacity: 0.6,
  paused: false,
};
/* Brand colours come from the Supercomponent tokens so the globe follows the theme. */
{
  const css = getComputedStyle(document.documentElement);
  const tok = (n, f) => (css.getPropertyValue(n).trim() || f);
  const royal = tok("--sc-color-royal-blue", params.accent), top = tok("--sc-color-top", params.background);
  /* Approved colorway: Royal Blue → Top (navy) gradient behind the globe. */
  Object.assign(params, { accent: royal, rimColor: royal, haloColor: royal, background: royal, background2: top });
}
Object.assign(params, window.MISSION_GLOBE_CONFIG || {});
const reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
const R2D = 180 / Math.PI, D2R = Math.PI / 180, EARTH_MI = 3958.8;

const toVec = (lat, lon, r = 1, out = new THREE.Vector3()) => {
  const a = lat * D2R, b = lon * D2R;
  return out.set(Math.cos(a) * Math.sin(b) * r, Math.sin(a) * r, Math.cos(a) * Math.cos(b) * r);
};

/* ---------- renderer / scene ---------- */
const canvas = document.getElementById("globe");
let renderer;
try { renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: "high-performance" }); }
catch (e) { document.getElementById("fallback").hidden = false; throw e; }
const DPR = Math.min(window.devicePixelRatio || 1, 1.75);
renderer.setPixelRatio(DPR);
renderer.setClearColor(0x000000, 0);   // transparent: the page background (solid or gradient) shows through

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(35, 1, 0.005, 20);
const axis = new THREE.Group(); scene.add(axis); // leans the polar axis (roll around the line of sight)
const globe = new THREE.Group(); globe.rotation.order = "XYZ"; axis.add(globe);

const accent = new THREE.Color(params.accent);
const missionColor = new THREE.Color(params.missionColor);
const U = { uMission: { value: missionColor }, uLight: { value: 0 }, uBase: { value: new THREE.Color(0.039, 0.078, 0.141) }, uLand: { value: new THREE.Color(0.33, 0.43, 0.60) }, uTime: { value: 0 }, uDpr: { value: DPR }, uColor: { value: accent }, uTrail: { value: params.trail }, uSize: { value: params.trailWidth } };

// land mask + elevation as textures (lat/lon space) for the line texture mode
const maskTex = (() => {
  const px = new Uint8Array(MASK_W * MASK_H);
  for (let i = 0; i < px.length; i++) px[i] = ((MASK[i >> 3] >> (7 - (i & 7))) & 1) * 255;
  const tx = new THREE.DataTexture(px, MASK_W, MASK_H, THREE.RedFormat, THREE.UnsignedByteType);
  tx.unpackAlignment = 1; tx.magFilter = tx.minFilter = THREE.LinearFilter; tx.needsUpdate = true; return tx;
})();
const elevTex = (() => { // 0.5° grid, same extent as the mask; relative elevation 0–255 (derived from a public-domain topography map)
  const bin = atob(""); const px = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) px[i] = bin.charCodeAt(i);
  const tx = new THREE.DataTexture(px, 390, 284, THREE.RedFormat, THREE.UnsignedByteType);
  tx.unpackAlignment = 1; tx.magFilter = tx.minFilter = THREE.LinearFilter; tx.needsUpdate = true; return tx;
})();
Object.assign(U, {
  uMode: { value: 0 }, uMask: { value: maskTex }, uElev: { value: elevTex },
  uSpacing: { value: 0.5 }, uMinW: { value: 0.1 }, uMaxW: { value: 0.75 }, uContrast: { value: 0.6 },
  uLift: { value: 0.8 }, uAngle: { value: 0 }, uLineOpacity: { value: 0.6 },
});

Object.assign(U, {
  uRim: { value: new THREE.Color(params.rimColor) }, uRimStrength: { value: params.rimStrength }, uRimPower: { value: params.rimTightness },
  uGlobeAlpha: { value: params.globeOpacity },
  uHalo: { value: new THREE.Color(params.haloColor) }, uHaloStrength: { value: params.haloStrength },
  uLandFront: { value: params.landFront }, uLandEdge: { value: params.landEdge },
  uLightDir: { value: new THREE.Vector3(0, 0, 1) }, uLightStrength: { value: params.lightStrength },
});
// ocean sphere with soft rim — also draws the elevation-line land texture when that mode is on
const globeMesh = new THREE.Mesh(new THREE.SphereGeometry(1, 128, 128), new THREE.ShaderMaterial({
  uniforms: U, transparent: true,
  vertexShader: `varying vec3 vN; varying vec3 vV; varying vec3 vP;
    void main(){ vP = position; vec4 mv = modelViewMatrix * vec4(position,1.); vN = normalize(normalMatrix*normal); vV = normalize(-mv.xyz); gl_Position = projectionMatrix*mv; }`,
  fragmentShader: `uniform vec3 uColor, uBase, uLand, uRim, uLightDir; uniform sampler2D uMask, uElev; uniform float uMode, uSpacing, uMinW, uMaxW, uContrast, uLift, uAngle, uLineOpacity, uRimStrength, uRimPower, uGlobeAlpha, uLandFront, uLandEdge, uLightStrength;
    varying vec3 vN; varying vec3 vV; varying vec3 vP;
    void main(){
      float f = pow(1. - max(dot(vN, vV), 0.), uRimPower);
      vec3 col = mix(uBase, uRim, f * uRimStrength);
      float alpha = uGlobeAlpha;
      if (uMode > 0.5) {
        vec3 p = normalize(vP);
        float lat = degrees(asin(p.y)), lon = degrees(atan(p.x, p.z));
        if (lon > 150.) lon -= 360.;
        vec2 uv = vec2((lon + 200.) / 195., (lat + 58.) / 142.);
        if (uv.x > 0. && uv.x < 1. && uv.y > 0. && uv.y < 1.) {
          float m = smoothstep(0.3, 0.7, texture2D(uMask, uv).r);
          float e = texture2D(uElev, uv).r;
          float a = radians(uAngle);
          // distance across the line direction, in degrees; elevation nudges lines north over high ground
          float c = lat * cos(a) + lon * cos(radians(lat)) * sin(a) + e * uLift;
          float q = c / uSpacing;
          float d = abs(fract(q) - 0.5);
          float w = 0.5 * mix(uMinW, uMaxW, pow(e, uContrast));
          float aa = fwidth(q) * 0.75;
          float line = 1. - smoothstep(w - aa, w + aa, d);
          float face = smoothstep(0.0, 0.35, dot(vN, vV));
          float lc = line * m * uLineOpacity * mix(uLandEdge, uLandFront, face) / max(uLandFront, 0.01);
          col = mix(col, uLand, lc); alpha = mix(alpha, 1., lc);
        }
      }
      float shade = mix(1., 0.25 + 1.0 * max(dot(vN, uLightDir), 0.), uLightStrength);
      gl_FragColor = vec4(col * shade, alpha);
    }`,
}));
globeMesh.renderOrder = -1;   // draw first so it hides what's behind it even when see-through
globe.add(globeMesh);

// atmosphere halo
const halo = new THREE.Mesh(new THREE.SphereGeometry(1.14, 64, 64), new THREE.ShaderMaterial({
  uniforms: { uHalo: U.uHalo, uHaloStrength: U.uHaloStrength, uLight: U.uLight }, side: THREE.BackSide, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false,
  vertexShader: `varying vec3 vN; varying vec3 vV; void main(){ vec4 mv = modelViewMatrix*vec4(position,1.); vN = normalize(normalMatrix*normal); vV = normalize(-mv.xyz); gl_Position = projectionMatrix*mv; }`,
  fragmentShader: `uniform vec3 uHalo; uniform float uLight, uHaloStrength; varying vec3 vN; varying vec3 vV;
    void main(){ float d = dot(vN, vV); float i = pow(clamp(d + 0.08, 0., 1.), 2.2) * smoothstep(0.62, 0.0, d);
      gl_FragColor = uLight > 0.5 ? vec4(uHalo, i * 0.22 * uHaloStrength) : vec4(uHalo * i * uHaloStrength, i * min(1., uHaloStrength * 1.8)); }`,
}));
globe.add(halo);

// graticule every 10°
const gratGeo = (() => {
  const p = [];
  for (let lat = -80; lat <= 80; lat += 10) for (let lon = -180; lon < 180; lon += 2) { p.push(...toVec(lat, lon, 1.0008).toArray(), ...toVec(lat, lon + 2, 1.0008).toArray()); }
  for (let lon = -180; lon < 180; lon += 10) for (let lat = -80; lat < 80; lat += 2) { p.push(...toVec(lat, lon, 1.0008).toArray(), ...toVec(lat + 2, lon, 1.0008).toArray()); }
  const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.Float32BufferAttribute(p, 3)); return g;
})();
const graticule = new THREE.LineSegments(gratGeo, new THREE.LineBasicMaterial({ color: 0x1a2a44, transparent: true, opacity: 0.55, depthWrite: false }));
globe.add(graticule);

// land dots
function isLand(lat, lon) {
  let lo = lon > 150 ? lon - 360 : lon;
  const c = Math.floor((lo - MASK_LON0) / MASK_RES), r = Math.floor((lat - MASK_LAT0) / MASK_RES);
  if (c < 0 || c >= MASK_W || r < 0 || r >= MASK_H) return false;
  const i = r * MASK_W + c;
  return (MASK[i >> 3] >> (7 - (i & 7))) & 1;
}
// land dots: an even (Fibonacci) scatter over the sphere, kept where the mask says land
const landMat = new THREE.ShaderMaterial({
  uniforms: { uDpr: U.uDpr, uLand: U.uLand, uLandFront: U.uLandFront, uLandEdge: U.uLandEdge, uLightDir: U.uLightDir, uLightStrength: U.uLightStrength }, transparent: true, depthWrite: false,
  vertexShader: `uniform float uDpr; uniform vec3 uLightDir; uniform float uLightStrength; varying float vF; varying float vShade;
    void main(){ vec4 mv = modelViewMatrix*vec4(position,1.); vec3 n = normalize(normalMatrix*position);
      vF = smoothstep(0.0, 0.45, dot(n, normalize(-mv.xyz)));
      vShade = mix(1., 0.25 + max(dot(n, uLightDir), 0.), uLightStrength);
      gl_PointSize = 2.1*uDpr; gl_Position = projectionMatrix*mv; }`,
  fragmentShader: `uniform vec3 uLand; uniform float uLandFront, uLandEdge; varying float vF; varying float vShade;
    void main(){ float r = length(gl_PointCoord-.5)*2.; if(r>1.) discard;
      gl_FragColor = vec4(uLand * vShade, mix(uLandEdge, uLandFront, vF) * smoothstep(1.,.4,r)); }`,
});
const land = new THREE.Points(new THREE.BufferGeometry(), landMat);
function buildLand(density) {
  const N = Math.round(150000 * density), GA = Math.PI * (3 - Math.sqrt(5)), out = new Float32Array(Math.ceil(N * 0.3) * 3), v = new THREE.Vector3();
  let n = 0;
  for (let i = 0; i < N; i++) {
    const lat = Math.asin(1 - (i + 0.5) / N * 2) * R2D;
    if (lat < -58 || lat > 84) continue;
    let lon = ((i * GA) * R2D) % 360; if (lon > 180) lon -= 360;
    if (lon > -5 && lon < 150) continue;               // far side of the globe never faces the camera
    if (isLand(lat, lon)) { toVec(lat, lon, 1.0015, v).toArray(out, n * 3); n++; }
  }
  land.geometry.dispose();
  const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.BufferAttribute(out.slice(0, n * 3), 3));
  land.geometry = g;
}
buildLand(params.dotDensity);
globe.add(land);

/* ---------- mission trails (GPU ring buffer) ---------- */
const SEG = 72, MAX_LEGS = 1400;
const trailPos = new Float32Array(MAX_LEGS * SEG * 3);
const trailS = new Float32Array(MAX_LEGS * SEG);
const trailTime = new Float32Array(MAX_LEGS * SEG * 2).fill(-1e6);
for (let j = 0; j < MAX_LEGS; j++) for (let k = 0; k < SEG; k++) { trailS[j * SEG + k] = k / (SEG - 1); trailTime[(j * SEG + k) * 2 + 1] = 1; }
const trailGeo = new THREE.BufferGeometry();
const aPos = new THREE.BufferAttribute(trailPos, 3).setUsage(THREE.DynamicDrawUsage);
const aTime = new THREE.BufferAttribute(trailTime, 2).setUsage(THREE.DynamicDrawUsage);
trailGeo.setAttribute("position", aPos); trailGeo.setAttribute("aS", new THREE.BufferAttribute(trailS, 1)); trailGeo.setAttribute("aTime", aTime);
trailGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 2);
const trails = new THREE.Points(trailGeo, new THREE.ShaderMaterial({
  uniforms: U, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
  vertexShader: `uniform float uTime, uTrail, uSize, uDpr; attribute float aS; attribute vec2 aTime; varying float vA; varying float vHead;
    void main(){
      float local = (uTime - aTime.x) / aTime.y;
      float e = mix(local, local*local*(3.-2.*local), 0.5);
      float head = (1. + uTrail) * (local < 1. ? e : local);
      float d = head - aS;
      if (local < 0. || d < 0. || d > uTrail) { gl_Position = vec4(2.,2.,2.,1.); gl_PointSize = 0.; return; }
      float k = 1. - d / uTrail; vA = k * k; vHead = smoothstep(0.035, 0.0, d);
      gl_PointSize = uSize * uDpr * (0.35 + 0.65 * k) + vHead * 3. * uDpr;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.);
    }`,
  fragmentShader: `uniform vec3 uMission; uniform float uLight; varying float vA; varying float vHead;
    void main(){ float r = length(gl_PointCoord-.5)*2.; if (r>1.) discard;
      float a = vA * smoothstep(1., 0.2, r);
      if (uLight > 0.5) { gl_FragColor = vec4(mix(uMission, uMission * 0.45, vHead * 0.8), a * 0.8); return; }
      vec3 c = mix(uMission, vec3(1.), vHead*0.75);
      gl_FragColor = vec4(c * a * 0.55, 1.); }`,
}));
globe.add(trails);
let legCursor = 0;

/* ---------- pulses (bases + destinations) ---------- */
function pulseMaterial(withCore) {
  return new THREE.ShaderMaterial({
    uniforms: U, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
    vertexShader: `uniform float uDpr, uTime; attribute float aStart; varying float vAge;
      void main(){ vAge = uTime - aStart; gl_PointSize = ${withCore ? "26." : "22."} * uDpr; gl_Position = projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
    fragmentShader: `uniform vec3 uMission; uniform float uLight; varying float vAge;
      void main(){ float r = length(gl_PointCoord-.5)*2.; float a = 0.;
        float t = vAge / 1.4;
        if (t >= 0. && t < 1.) { float rr = mix(0.12, 1.0, 1.-pow(1.-t,2.)); a += smoothstep(0.09, 0., abs(r-rr)) * (1.-t) * 0.9; }
        ${withCore
          ? "a += smoothstep(0.2, 0.12, r) * 0.95; a += smoothstep(0.34, 0.2, r) * 0.25;"
          : "if (t >= 0. && t < 1.6) a += smoothstep(0.16, 0.05, r) * (1.-t/1.6) * 0.8;"}
        if (a <= 0.001) discard;
        if (uLight > 0.5) { gl_FragColor = vec4(uMission * ${withCore ? "mix(1., 0.6, smoothstep(0.2,0.,r))" : "0.9"}, min(a, 1.)); return; }
        vec3 c = mix(uMission, vec3(1.), ${withCore ? "smoothstep(0.2,0.,r)*0.55" : "0.3"});
        gl_FragColor = vec4(c * a, 1.); }`,
  });
}
const basePos = new Float32Array(BASES.length * 3), baseStart = new Float32Array(BASES.length).fill(-100);
BASES.forEach((b, i) => { b.v = toVec(b.lat, b.lon, 1); toVec(b.lat, b.lon, 1.002).toArray(basePos, i * 3); b.rate = b.fpy / 525600; });
const baseGeo = new THREE.BufferGeometry();
baseGeo.setAttribute("position", new THREE.BufferAttribute(basePos, 3));
const aBaseStart = new THREE.BufferAttribute(baseStart, 1).setUsage(THREE.DynamicDrawUsage); baseGeo.setAttribute("aStart", aBaseStart);
globe.add(new THREE.Points(baseGeo, pulseMaterial(true)));

const MAX_PULSE = 400, pulsePos = new Float32Array(MAX_PULSE * 3), pulseStart = new Float32Array(MAX_PULSE).fill(-100);
const pulseGeo = new THREE.BufferGeometry();
const aPulsePos = new THREE.BufferAttribute(pulsePos, 3).setUsage(THREE.DynamicDrawUsage);
const aPulseStart = new THREE.BufferAttribute(pulseStart, 1).setUsage(THREE.DynamicDrawUsage);
pulseGeo.setAttribute("position", aPulsePos); pulseGeo.setAttribute("aStart", aPulseStart);
pulseGeo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 2);
globe.add(new THREE.Points(pulseGeo, pulseMaterial(false)));
let pulseCursor = 0;

/* ---------- mission simulation ---------- */
const tmpA = new THREE.Vector3(), tmpB = new THREE.Vector3(), tmpP = new THREE.Vector3();
function destinationFrom(b) {
  for (let tries = 0; tries < 8; tries++) {
    const mi = 18 + 125 * Math.pow(Math.random(), 1.7);                 // most flights 20–150 mi
    const ang = (mi * params.distanceScale) / EARTH_MI, brg = Math.random() * Math.PI * 2;
    const la1 = b.lat * D2R, lo1 = b.lon * D2R;
    const la2 = Math.asin(Math.sin(la1) * Math.cos(ang) + Math.cos(la1) * Math.sin(ang) * Math.cos(brg));
    const lo2 = lo1 + Math.atan2(Math.sin(brg) * Math.sin(ang) * Math.cos(la1), Math.cos(ang) - Math.sin(la1) * Math.sin(la2));
    const lat = la2 * R2D, lon = lo2 * R2D;
    if (isLand(lat, lon) || tries === 7) return { lat, lon, mi, ang };
  }
}
function writeLeg(from, to, ang, heightK, start, dur) {
  const j = legCursor; legCursor = (legCursor + 1) % MAX_LEGS;
  const H = (0.0025 + ang * 0.55) * params.arcHeight * heightK;
  const sinA = Math.sin(ang) || 1e-6;
  for (let k = 0; k < SEG; k++) {
    const s = k / (SEG - 1);
    const w1 = Math.sin((1 - s) * ang) / sinA, w2 = Math.sin(s * ang) / sinA;   // slerp
    tmpP.copy(from).multiplyScalar(w1).addScaledVector(to, w2).normalize().multiplyScalar(1.002 + H * Math.sin(Math.PI * s));
    tmpP.toArray(trailPos, (j * SEG + k) * 3);
    trailTime[(j * SEG + k) * 2] = start; trailTime[(j * SEG + k) * 2 + 1] = dur;
  }
  aPos.addUpdateRange(j * SEG * 3, SEG * 3); aPos.needsUpdate = true;
  aTime.addUpdateRange(j * SEG * 2, SEG * 2); aTime.needsUpdate = true;
}
function arrivalFraction(trail) { // solve head(local) = 1 for the eased curve used in the shader
  let lo = 0, hi = 1; const target = 1 / (1 + trail);
  for (let i = 0; i < 24; i++) { const m = (lo + hi) / 2, e = 0.5 * m + 0.5 * m * m * (3 - 2 * m); (e < target ? (lo = m) : (hi = m)); }
  return (lo + hi) / 2;
}
function addPulse(v, start) {
  const i = pulseCursor; pulseCursor = (pulseCursor + 1) % MAX_PULSE;
  tmpP.copy(v).multiplyScalar(1.002).toArray(pulsePos, i * 3); pulseStart[i] = start;
  aPulsePos.addUpdateRange(i * 3, 3); aPulsePos.needsUpdate = true; aPulseStart.addUpdateRange(i, 1); aPulseStart.needsUpdate = true;
}
const missions = []; // end times, for "airborne now"
let missionCount = 0;
function launch(bi, now) {
  const b = BASES[bi], d = destinationFrom(b);
  toVec(d.lat, d.lon, 1, tmpB); tmpA.copy(b.v);
  const dur = params.flightSeconds * (0.75 + d.mi / 150 * 0.6) / Math.max(0.2, 1 - params.trail * 0.4);
  const arrive = now + dur * arrivalFraction(params.trail);
  const dwell = 0.5 + Math.random() * 0.6;
  writeLeg(tmpA, tmpB, d.ang, 1.0, now, dur);                    // outbound
  writeLeg(tmpB, tmpA, d.ang, 0.55, arrive + dwell, dur);       // return, lower arc
  baseStart[bi] = now; aBaseStart.addUpdateRange(bi, 1); aBaseStart.needsUpdate = true;
  addPulse(tmpB, arrive);
  missions.push(arrive + dwell + dur * arrivalFraction(params.trail));
  missionCount++;
}
// launches per sim-minute follow a daily curve: quiet overnight, peak mid-afternoon (normalized to average 1)
const diurnal = (h) => (0.45 + 1.1 * Math.exp(-(((h - 15) / 5) ** 2))) / 0.856;
function poisson(l) { if (l > 20) return Math.max(0, Math.round(l + Math.sqrt(l) * (Math.random() * 2 - 1) * 1.7)); let k = 0, p = 1, L = Math.exp(-l); do { k++; p *= Math.random(); } while (p > L); return k - 1; }

let realT = 0, simMin = 0;
const frameMinutes = () => (params.timeframe === "24 hours" ? 1440 : 10080);
function step(dt) {
  realT += dt; U.uTime.value = realT;
  const minsPerSec = frameMinutes() / params.loopSeconds;
  const simDt = dt * minsPerSec;
  simMin += simDt;
  if (simMin >= frameMinutes()) { simMin -= frameMinutes(); missionCount = 0; }
  const f = diurnal((simMin / 60) % 24) * params.activity;
  for (let i = 0; i < BASES.length; i++) {
    const n = poisson(BASES[i].rate * f * simDt);
    for (let k = 0; k < n; k++) launch(i, realT + Math.random() * dt);
  }
  missions.sort((a, b) => a - b);
  while (missions.length && missions[0] < realT) missions.shift();
}

/* ---------- camera / framing ---------- */
let view = { ...FRAMINGS[params.framing] }, scrollP = 0;
function layout() {
  const w = canvas.clientWidth, h = canvas.clientHeight;
  renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
}
function placeCamera() {
  const portrait = camera.aspect < 1;
  const effDist = view.dist / params.zoom;
  const dist = effDist * (portrait ? 1 / Math.max(0.55, camera.aspect) * 0.8 : 1);
  const t = params.tilt * D2R;
  camera.position.set(0, -Math.sin(t) * dist, 1 + Math.cos(t) * dist);
  camera.lookAt(0, portrait ? 0.02 : 0, 1);
  // scroll turns the globe west → east across the section; a tiny idle drift keeps it alive
  const idle = reduceMotion ? 0 : Math.sin(realT * 0.05) * 0.6;
  const lon = view.lon + (0.5 - scrollP) * 2 * view.sweep + idle;
  const lat = view.lat - scrollP * 3;
  // shift framing right on wide screens so copy on the left has room
  const shift = portrait ? 0 : params.offset * Math.min(1.3, Math.max(0, (camera.aspect - 1) / 0.6)) * (effDist / 1.21);
  globe.rotation.y = -(lon - shift) * D2R; globe.rotation.x = lat * D2R;
  axis.rotation.z = -params.axisTilt * D2R;
}

/* ---------- scroll ---------- */
if (window.gsap && window.ScrollTrigger) {
  gsap.registerPlugin(ScrollTrigger);
  ScrollTrigger.create({ trigger: "#missions", start: "top top", end: "bottom bottom", scrub: 1.2, onUpdate: (st) => { scrollP = st.progress; } });
} else {
  addEventListener("scroll", () => { const s = document.getElementById("missions"); const r = s.getBoundingClientRect(); scrollP = Math.min(1, Math.max(0, -r.top / (r.height - innerHeight))); }, { passive: true });
}

/* ---------- HUD + copy stats ---------- */
const DAYS = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
const $ = (id) => document.getElementById(id);
const totalYear = BASES.reduce((s, b) => s + b.fpy, 0);
/* the stat spans are optional — the page may drop beats */
const setText = (id, v) => { const el = $(id); if (el) el.textContent = v; };
setText("statYear", totalYear.toLocaleString("en-US"));
setText("statBases", BASES.length);
setText("statEvery", Math.max(1, Math.round(525600 / totalYear)));
$("hudBases").textContent = BASES.length;
function hud() {
  const d = Math.floor(simMin / 1440), h = Math.floor((simMin % 1440) / 60), m = Math.floor(simMin % 60);
  $("hudClock").textContent = (params.timeframe === "7 days" ? DAYS[d % 7] + " " : "") + String(h).padStart(2, "0") + ":" + String(m).padStart(2, "0");
  $("hudFrame").textContent = params.timeframe === "7 days" ? "week" : "day";
  $("hudCount").textContent = missionCount.toLocaleString("en-US");
  $("hudAir").textContent = missions.length;
}

/* ---------- color scheme (dark default, inverted = light) ---------- */
const glowMats = [halo.material, trails.material, ...globe.children.filter((o) => o.isPoints && o.material.uniforms && o.material.uniforms.uTime && o !== trails).map((o) => o.material)];
const gratMat = graticule.material;
function applyGlobe() {
  // globe settings apply to the dark scheme; inverted uses a fixed light globe
  const light = params.inverted;
  if (light) { U.uBase.value.set(0xe4eaf3); U.uLand.value.set(0x6f7f99); gratMat.color.set(0xc7d1e0); }
  else {
    if (params.globeMatchBg) U.uBase.value.set(params.background).offsetHSL(0, 0, params.globeShift);
    else U.uBase.value.set(params.globeColor);
    U.uLand.value.set(params.landColor); gratMat.color.set(params.gridColor);
  }
  gratMat.opacity = params.gridOpacity;
  U.uRim.value.set(params.rimColor); U.uRimStrength.value = params.rimStrength; U.uRimPower.value = params.rimTightness;
  U.uGlobeAlpha.value = params.globeOpacity;
  U.uHalo.value.set(params.haloColor); U.uHaloStrength.value = params.haloStrength;
  halo.visible = params.haloOn; halo.scale.setScalar(params.haloSize / 1.14);
  U.uLandFront.value = params.landFront; U.uLandEdge.value = params.landEdge;
  const az = params.lightAngle * D2R, el = params.lightHeight * D2R;   // 0° = from the top, 90° = from the right
  U.uLightDir.value.set(Math.cos(el) * Math.sin(az), Math.cos(el) * Math.cos(az), Math.sin(el)).normalize();
  U.uLightStrength.value = params.lightStrength;
  if (typeof globeCtrls !== "undefined") { globeCtrls.color.show(!params.globeMatchBg); globeCtrls.shift.show(params.globeMatchBg); }
}
function applyBackground() {
  // background settings apply to the dark scheme; inverted uses a fixed light ground
  const root = document.getElementById("missions").style;
  if (params.inverted) { root.setProperty("--ink", "#f2f5fa"); root.setProperty("--bg-fill", "#f2f5fa"); return; }
  const a = params.background, b = params.background2;
  const fill = params.bgMode === "Linear gradient" ? `linear-gradient(${params.bgAngle}deg, ${a}, ${b})`
             : params.bgMode === "Radial gradient" ? `radial-gradient(ellipse at ${params.bgX}% ${params.bgY}%, ${a} 0%, ${b} 100%)`
             : a;
  root.setProperty("--ink", a);        // text scrims and shadows use the main color
  if (params.globeMatchBg) applyGlobe();
  root.setProperty("--bg-fill", fill);
  if (typeof bgCtrls !== "undefined") {
    const grad = params.bgMode !== "Solid";
    bgCtrls.b2.show(grad); bgCtrls.angle.show(params.bgMode === "Linear gradient");
    bgCtrls.x.show(params.bgMode === "Radial gradient"); bgCtrls.y.show(params.bgMode === "Radial gradient");
    bgCtrls.c1.name(grad ? "Background 1" : "Background");
  }
}
function setScheme(light) {
  document.documentElement.classList.toggle("inverted", light);
  U.uLight.value = light ? 1 : 0;
  applyBackground();
  applyGlobe();
  for (const m of glowMats) { m.blending = light ? THREE.NormalBlending : THREE.AdditiveBlending; m.needsUpdate = true; }
}

/* ---------- apply settings (also re-run by the panel) ---------- */
function setLandMode(m) {
  const lines = m === "Elevation lines";
  U.uMode.value = lines ? 1 : 0; land.visible = !lines;
}
function applyAll() {
  const root = document.getElementById("missions");
  root.style.setProperty("--mission", params.missionColor);
  if (params.inverted) setScheme(true);
  applyBackground(); applyGlobe(); setLandMode(params.landMode);
  U.uSpacing.value = params.lineSpacing; U.uMinW.value = params.lineMin; U.uMaxW.value = params.lineMax;
  U.uContrast.value = params.lineContrast; U.uLift.value = params.lineLift; U.uAngle.value = params.lineAngle; U.uLineOpacity.value = params.lineOpacity;
  U.uTrail.value = params.trail; U.uSize.value = params.trailWidth;
  graticule.visible = params.graticule;
  root.classList.toggle("is-clean", !params.showCopy);
  root.classList.toggle("is-no-shade", !params.showShade);
  const legend = root.querySelector(".coverage_legend"); if (legend) legend.hidden = !params.showLegend;
  const hudBox = root.querySelector(".coverage_hud"); if (hudBox) hudBox.hidden = !params.hud;
}
applyAll();

/* ---------- loop: pause offscreen, freeze for reduced motion ---------- */
let visible = true, last = performance.now();
new IntersectionObserver(([e]) => { visible = e.isIntersecting; last = performance.now(); }).observe(document.getElementById("stage"));
layout();
addEventListener("resize", layout);
// pre-warm so the first frame already shows missions in flight
for (let i = 0; i < 360; i++) step(1 / 60);
function frame(now) {
  requestAnimationFrame(frame);
  if (!visible) return;
  const dt = Math.min(0.05, (now - last) / 1000); last = now;
  if (!params.paused && !reduceMotion) step(dt);
  placeCamera();
  if (params.hud) hud();
  renderer.render(scene, camera);
}
requestAnimationFrame(frame);

/* ---------- tuning panel (only with ?controls) ---------- */
if (CONTROLS) {
  const { default: GUI } = await import("https://cdn.jsdelivr.net/npm/lil-gui@0.19.2/dist/lil-gui.esm.min.js");
  const gui = new GUI({ title: "Prototype controls" });
  const fColor = gui.addFolder("Colors");
  fColor.addColor(params, "accent").name("Brand blue").onChange((c) => { accent.set(c); document.getElementById("missions").style.setProperty("--sc-color-accent", c); });
  fColor.addColor(params, "missionColor").name("Dots + streaks").onChange((c) => { missionColor.set(c); document.getElementById("missions").style.setProperty("--mission", c); });
  fColor.add(params, "bgMode", ["Solid", "Linear gradient", "Radial gradient"]).name("Background type").onChange(applyBackground);
  var bgCtrls = {
    c1: fColor.addColor(params, "background").name("Background").onChange(applyBackground),
    b2: fColor.addColor(params, "background2").name("Background 2").onChange(applyBackground),
    angle: fColor.add(params, "bgAngle", 0, 360, 1).name("Angle (°)").onChange(applyBackground),
    x: fColor.add(params, "bgX", 0, 100, 1).name("Center X (%)").onChange(applyBackground),
    y: fColor.add(params, "bgY", 0, 100, 1).name("Center Y (%)").onChange(applyBackground),
  };
  fColor.add(params, "inverted").name("Invert colors").onChange(setScheme);
  const fGlobe = gui.addFolder("Globe");
  fGlobe.add(params, "globeMatchBg").name("Match background").onChange(applyGlobe);
  var globeCtrls = {
    color: fGlobe.addColor(params, "globeColor").name("Globe color").onChange(applyGlobe),
    shift: fGlobe.add(params, "globeShift", -0.3, 0.3, 0.01).name("Darker ↔ lighter").onChange(applyGlobe),
  };
  fGlobe.add(params, "globeOpacity", 0, 1, 0.01).name("Globe opacity").onChange(applyGlobe);
  const fRim = fGlobe.addFolder("Rim glow");
  fRim.addColor(params, "rimColor").name("Color").onChange(applyGlobe);
  fRim.add(params, "rimStrength", 0, 1, 0.01).name("Strength").onChange(applyGlobe);
  fRim.add(params, "rimTightness", 1, 8, 0.1).name("Tightness").onChange(applyGlobe);
  const fHalo = fGlobe.addFolder("Atmosphere halo");
  fHalo.add(params, "haloOn").name("Show").onChange(applyGlobe);
  fHalo.addColor(params, "haloColor").name("Color").onChange(applyGlobe);
  fHalo.add(params, "haloStrength", 0, 1.5, 0.01).name("Strength").onChange(applyGlobe);
  fHalo.add(params, "haloSize", 1.02, 1.4, 0.005).name("Size").onChange(applyGlobe);
  const fLandC = fGlobe.addFolder("Land color");
  fLandC.addColor(params, "landColor").name("Color").onChange(applyGlobe);
  fLandC.add(params, "landFront", 0, 1, 0.01).name("Opacity (front)").onChange(applyGlobe);
  fLandC.add(params, "landEdge", 0, 1, 0.01).name("Opacity (edges)").onChange(applyGlobe);
  const fGrid = fGlobe.addFolder("Grid");
  fGrid.addColor(params, "gridColor").name("Color").onChange(applyGlobe);
  fGrid.add(params, "gridOpacity", 0, 1, 0.01).name("Opacity").onChange(applyGlobe);
  const fSun = fGlobe.addFolder("Lighting");
  fSun.add(params, "lightStrength", 0, 1, 0.01).name("Strength (0 = off)").onChange(applyGlobe);
  fSun.add(params, "lightAngle", -180, 180, 1).name("Direction (°)").onChange(applyGlobe);
  fSun.add(params, "lightHeight", 0, 90, 1).name("Height (°)").onChange(applyGlobe);
  fRim.close(); fHalo.close(); fLandC.close(); fGrid.close(); fSun.close();
  applyGlobe();
  const fSim = gui.addFolder("Timeline");
  fSim.add(params, "timeframe", ["24 hours", "7 days"]).name("Timeframe").onChange(() => { simMin = 0; missionCount = 0; });
  fSim.add(params, "loopSeconds", 15, 180, 1).name("Loop length (s)");
  fSim.add(params, "activity", 0.25, 4, 0.05).name("Activity ×");
  fSim.add(params, "paused").name("Pause");
  const fLook = gui.addFolder("Trails");
  fLook.add(params, "flightSeconds", 0.6, 5, 0.1).name("Flight time (s)");
  fLook.add(params, "trail", 0.15, 1, 0.01).name("Trail length").onChange((v) => (U.uTrail.value = v));
  fLook.add(params, "trailWidth", 1, 8, 0.1).name("Trail width").onChange((v) => (U.uSize.value = v));
  fLook.add(params, "arcHeight", 0, 3, 0.05).name("Arc height ×");
  fLook.add(params, "distanceScale", 1, 4, 0.05).name("Distance ×");
  const fCam = gui.addFolder("Framing");
  fCam.add(params, "framing", Object.keys(FRAMINGS)).name("Preset").onChange((k) => { window.gsap ? gsap.to(view, { ...FRAMINGS[k], duration: 1.6, ease: "power2.inOut" }) : (view = { ...FRAMINGS[k] }); });
  fCam.add(params, "zoom", 0.5, 3, 0.01).name("Zoom ×");
  fCam.add(params, "tilt", 0, 45, 1).name("Tilt (°)");
  fCam.add(params, "offset", 0, 70, 1).name("Shift right (°)");
  fCam.add(params, "axisTilt", -35, 35, 0.5).name("Polar axis tilt (°)");
  fCam.add(params, "graticule").name("Lat/long grid").onChange((v) => (graticule.visible = v));
  applyBackground();
  const fLand = gui.addFolder("Land texture");
  fLand.add(params, "landMode", ["Dots", "Elevation lines"]).name("Mode").onChange((m) => { setLandMode(m); showLandFolders(m); });
  const fDots = fLand.addFolder("Dots"), fLines = fLand.addFolder("Elevation lines");
  const showLandFolders = (m) => { fDots.show(m === "Dots"); fLines.show(m !== "Dots"); };
  fDots.add(params, "dotDensity", 0.2, 4, 0.05).name("Dot density ×").onChange(buildLand);
  fLines.add(params, "lineSpacing", 0.15, 2, 0.01).name("Line spacing (°)").onChange((v) => (U.uSpacing.value = v));
  fLines.add(params, "lineMin", 0, 0.6, 0.01).name("Thinnest (low ground)").onChange((v) => (U.uMinW.value = v));
  fLines.add(params, "lineMax", 0.05, 1, 0.01).name("Thickest (high ground)").onChange((v) => (U.uMaxW.value = v));
  fLines.add(params, "lineContrast", 0.2, 3, 0.05).name("Elevation contrast").onChange((v) => (U.uContrast.value = v));
  fLines.add(params, "lineLift", 0, 4, 0.05).name("Ridge lift (°)").onChange((v) => (U.uLift.value = v));
  fLines.add(params, "lineAngle", -90, 90, 1).name("Line angle (°)").onChange((v) => (U.uAngle.value = v));
  fLines.add(params, "lineOpacity", 0.1, 1, 0.01).name("Line opacity").onChange((v) => (U.uLineOpacity.value = v));
  showLandFolders(params.landMode);
  const fRec = gui.addFolder("Recording");
  fRec.add(params, "showCopy").name("Left column text").onChange((v) => document.getElementById("missions").classList.toggle("is-clean", !v));
  fRec.add(params, "showShade").name("Text shading").onChange((v) => document.getElementById("missions").classList.toggle("is-no-shade", !v));
  fRec.add(params, "showLegend").name("Legend").onChange((v) => { document.querySelector(".coverage_legend").hidden = !v; });
  fRec.add({ tip: "Press H to hide this panel" }, "tip").name("Tip").disable();
  addEventListener("keydown", (e) => { if ((e.key === "h" || e.key === "H") && !e.metaKey && !e.ctrlKey && !/input|textarea|select/i.test(e.target.tagName)) gui.domElement.hidden = !gui.domElement.hidden; });
  fCam.add(params, "hud").name("Clock + counts").onChange((v) => { document.querySelector(".coverage_hud").hidden = !v; });
  fSim.close(); fLook.close();
  if (innerWidth < 720) gui.close();

  /* keep the viewer's tweaks across reloads, and let them copy the full set */
  const STORE = "mission-globe-settings";
  try { const saved = JSON.parse(localStorage.getItem(STORE) || "null"); if (saved) gui.load(saved); } catch (e) {}
  gui.onFinishChange(() => { try { localStorage.setItem(STORE, JSON.stringify(gui.save())); } catch (e) {} });
  const copyOut = document.createElement("textarea");
  copyOut.id = "settingsOut"; copyOut.readOnly = true; copyOut.hidden = true;
  copyOut.style.cssText = "position:fixed;left:12px;bottom:12px;z-index:11;width:min(420px,calc(100vw - 24px));height:160px;font:11px/1.4 var(--mono);background:#0c1422;color:#cfe0ff;border:1px solid #2a3a5c;border-radius:8px;padding:10px";
  document.body.appendChild(copyOut);
  const actions = { copy() {
    const { paused, ...cfg } = params; const json = JSON.stringify(cfg, null, 2);   // paste into window.MISSION_GLOBE_CONFIG
    const done = () => { copyBtn.name("Copied ✓"); setTimeout(() => copyBtn.name("Copy settings"), 1600); };
    const fallback = () => { copyOut.value = json; copyOut.hidden = false; copyOut.focus(); copyOut.select(); copyBtn.name("Select + copy below"); };
    try { navigator.clipboard.writeText(json).then(done, fallback); } catch (e) { fallback(); }
  }};
  const copyBtn = gui.add(actions, "copy").name("Copy settings");
  copyOut.addEventListener("blur", () => { copyOut.hidden = true; copyBtn.name("Copy settings"); });

}
